$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
Add-Type -ReferencedAssemblies System.Drawing.Common,System.Drawing.Primitives,System.Runtime,System.Collections,System.Runtime.InteropServices,System.Private.Windows.GdiPlus,System.Private.Windows.Core,System.Console -TypeDefinition @"
using System;using System.Drawing;using System.Drawing.Imaging;using System.Collections.Generic;
public class HandCursorImport{
 static byte[] Read(Bitmap b){var d=b.LockBits(new Rectangle(0,0,b.Width,b.Height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);var a=new byte[d.Stride*b.Height];System.Runtime.InteropServices.Marshal.Copy(d.Scan0,a,0,a.Length);b.UnlockBits(d);return a;}
 static void Save(byte[] a,int w,int h,string file){using(var b=new Bitmap(w,h,PixelFormat.Format32bppArgb)){var d=b.LockBits(new Rectangle(0,0,w,h),ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);System.Runtime.InteropServices.Marshal.Copy(a,0,d.Scan0,a.Length);b.UnlockBits(d);b.Save(file);}}
 static byte[] Sample(byte[] src,int w,int h,double px,double py){int x=(int)Math.Floor(px),y=(int)Math.Floor(py);double fx=px-x,fy=py-y,a=0,r=0,g=0,b=0;for(int dy=0;dy<2;dy++)for(int dx=0;dx<2;dx++){int xx=x+dx,yy=y+dy;if(xx<0||yy<0||xx>=w||yy>=h)continue;double k=(dx==0?1-fx:fx)*(dy==0?1-fy:fy),aa=src[(yy*w+xx)*4+3]/255.0;int at=(yy*w+xx)*4;a+=aa*k;b+=src[at]*aa*k;g+=src[at+1]*aa*k;r+=src[at+2]*aa*k;}return new byte[]{(byte)Math.Clamp(Math.Round(b/Math.Max(a,.00001)),0,255),(byte)Math.Clamp(Math.Round(g/Math.Max(a,.00001)),0,255),(byte)Math.Clamp(Math.Round(r/Math.Max(a,.00001)),0,255),(byte)Math.Clamp(Math.Round(a*255),0,255)};}
 public static void Build(string root){using(var b=new Bitmap(System.IO.Path.Combine(root,"original.png"))){int w=b.Width,h=b.Height;var src=Read(b);var seen=new bool[w*h];var largest=new List<int>();for(int i=0;i<w*h;i++){if(seen[i]||src[i*4+3]<160)continue;var cells=new List<int>();var q=new Queue<int>();q.Enqueue(i);seen[i]=true;while(q.Count>0){int k=q.Dequeue(),x=k%w;cells.Add(k);foreach(int j in new int[]{k-1,k+1,k-w,k+w}){if(j<0||j>=w*h||Math.Abs(j%w-x)>1||seen[j]||src[j*4+3]<160)continue;seen[j]=true;q.Enqueue(j);}}if(cells.Count>largest.Count)largest=cells;}
 int l=w,r=0,t=h,bt=0,tip=largest[0];foreach(int k in largest){l=Math.Min(l,k%w);r=Math.Max(r,k%w);t=Math.Min(t,k/w);bt=Math.Max(bt,k/w);if(k%w+k/w<tip%w+tip/w)tip=k;}l=Math.Max(0,l-3);r=Math.Min(w-1,r+3);t=Math.Max(0,t-3);bt=Math.Min(h-1,bt+3);int cw=r-l+1,ch=bt-t+1;var clean=new byte[cw*ch*4];foreach(int k in largest)for(int dy=-2;dy<=2;dy++)for(int dx=-2;dx<=2;dx++){int xx=k%w+dx,yy=k/w+dy;if(xx<l||xx>r||yy<t||yy>bt)continue;Array.Copy(src,(yy*w+xx)*4,clean,((yy-t)*cw+xx-l)*4,4);}
 string dir=System.IO.Path.Combine(root,"derived");System.IO.Directory.CreateDirectory(dir);string cropped=System.IO.Path.Combine(dir,"source.png");Save(clean,cw,ch,cropped);int dh=44,dw=(int)Math.Round(cw*44.0/ch),fw=dw+8,fh=52;byte[] baseFrame;using(var small=new Bitmap(fw,fh,PixelFormat.Format32bppArgb))using(var g=Graphics.FromImage(small))using(var image=new Bitmap(cropped)){g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;g.DrawImage(image,4,4,dw,dh);baseFrame=Read(small);}int hx=(int)Math.Round((tip%w-l)*44.0/ch+4),hy=(int)Math.Round((tip/w-t)*44.0/ch+4);
 for(int f=0;f<3;f++){var frame=(byte[])baseFrame.Clone();double key=f==1?1:(f==2?-1:0);for(int y=0;y<fh;y++)for(int x=0;x<fw;x++){double distance=Math.Sqrt((x-hx)*(x-hx)+(y-hy)*(y-hy)),weight=Math.Clamp((distance-8)/18.0,0,1);weight=weight*weight*(3-2*weight);if(weight==0||f==0)continue;double px=x+Math.Sin(y*.37+1.3)*.48*key*weight,py=y+Math.Cos(x*.39-.5)*.38*key*weight;Array.Copy(Sample(baseFrame,fw,fh,px,py),0,frame,(y*fw+x)*4,4);}Save(frame,fw,fh,System.IO.Path.Combine(dir,"frame_"+f+".png"));}
 string gd="extends RefCounted\nconst SIZE := Vector2i("+fw+","+fh+")\nconst HOTSPOT := Vector2("+hx+","+hy+")\nconst FPS := 8.0\n";System.IO.File.WriteAllText(System.IO.Path.Combine(root,"regions.gd"),gd);Console.WriteLine("CURSOR source="+w+"x"+h+" crop="+cw+"x"+ch+" frame="+fw+"x"+fh+" hotspot="+hx+","+hy);}}
}
"@
[HandCursorImport]::Build((Join-Path $PSScriptRoot '../godot/assets/UI/HUD/hand_cursor'))
